# (dernière position du palier, niveau visé, points par question)
BAREME = [(4, "A1", 3), (10, "A2", 9), (19, "B1", 15), (29, "B2", 21), (35, "C1", 26), (39, "C2", 33)]


def palier(position: int) -> tuple[str, int]:
    return next((level, points) for last, level, points in BAREME if position <= last)


